import sys
from typing import List, Tuple

def calculate_sums(points: List[Tuple[int, int]]) -> int:
    if len(points) == 2:
        return 1
    elif len(points) == 3:
        return 8

    n = len(points)
    sums = [0] * n
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = dp[1][1] = dp[2][2] = 8
    for i in range(3, n + 1):
        dp[i][i - 1] = dp[i - 1][i - 2] = dp[i - 2][i - 3] = 4
    for j in range(3, n):
        sums[0] += dp[j][j - 1]
        sums[1] += dp[j - 1][j - 2]
        sums[2] += dp[j - 2][j - 3]
    for i in range(3, len(points)):
        for j in range(i + 1, len(points)):
            a, b = points[i], points[j]
            cx = (a[0] + b[0]) // 2
            cy = (a[1] + b[1]) // 2
            hit = 1
            for point in points:
                ax, ay = point
                if ax * (cy - ay) + ay * (ax - cx) + (ax - cx) * (cy - ay) == 0:
                    hit = 0
                    break
            if hit:
                l = 1
                r = j - 1
                found = 0
                while l <= r:
                    mid = (l + r) // 2
                    if points[mid] == b:
                        found = mid
                        break
                    elif found and points[mid] > b:
                        r = mid - 1
                    else:
                        l = mid + 1
                if not found or points[found] != b:
                    sums[3] += dp[i][j - 1]

    return sum(sums) * ((n * (n - 1)) // 4) - 4 * sums[3]

if __name__ == "__main__":
    points = []
    for _ in range(int(input())):
        x, y = map(int, input().split())
        points.append((x, y))
    print(calculate_sums(points))
