from collections import deque

def find_dream_duration(n, directions):
    max_duration = [None] * (n + 1)
    end_indices = deque([(0, 'U')])  # (index, direction)
    for step in range(1, n + 1):
        current_direction, max_duration[step] = end_indices[0]
        for index, direction in end_indices:
            if direction == 'U':
                current_direction = 'D'
            elif direction == 'D':
                current_direction = 'U'

            # Calculate the new maximum duration step
            new_end_index = (index, current_direction)
            if new_end_index[0] == step:
                if new_end_index[1] == 'U':
                    new_duration = step + 1
                else:
                    new_duration = 1
            else:
                new_duration = max_duration[index] + 1

            if directions[index - 1] == current_direction:
                end_indices.popleft()  # Remove traces of the current step
            else:
                continue  # Directions are distinct

            end_indices.append(new_end_index)
            if new_duration < max_duration[step]:
                max_duration[step] = new_duration
        if not end_indices:  # Optimization: Once all pointers have been exhausted
            break

    return max_duration

# Read input
