from collections import Counter

def make_almost_unique(nums):
    n = len(nums)
    if n % 2 != 0:
        return "NO"

    counter = Counter(nums)
    max_possible = (n // 2) * (n - 1) // 2
    removed = 0

    for count in counter.values():
        if count > 2:
            removed += (count - 3) // 2
        elif count == 2 or count == 3:
            removed += 1

    if removed > max_possible:
        return "YES"
    else:
        return "NO"

def split_unique_to_almost_unique(nums):
    n = len(nums)
    total_diff = 0
    difference = (n * (n - 1)) // 2

    visited = [False] * n
    current_num = 0
    index = 0

    while total_diff < max_possible:
        while index < n and not visited[index]:
            visited[index] = True
            current_num = max(current_num, nums[index])
            index += 1

        if total_diff + (N - len(nums.index(current_num, start=index))) > max_possible:
            break

        difference -= total_diff
        total_diff += (N - len(nums.index(current_num, start=index)))

    total_diff = len(nums) - difference

    if total_diff <= max_possible - len(nums) or max_possible - len(nums) == 0 and len(nums) == 1:
        return "YES"
    else:
        return "NO"

