# Function to compute the inclination of a line between two points
def inclination(a, b):
    A, B, C = a, b
    if C[0] == 0: return "infinite slope"
    return (float(C[1]) - A[1]) / (float(C[0]) - A[0])

# Function to check if three points are collinear
def are_collinear(a, b, c):
    return inclination([a[0], a[1]], [b[0], b[1]]) == inclination([a[0], a[1]], [c[0], c[1]])

# Helper function to create the blocking tuples
def get_blocking_tuples(ranges):
    t1 = range(ranges[0][0], ranges[0][1] + 1)
    t2 = range(ranges[1][0], ranges[1][1] + 1)
    return list(itertools.product(t1, t2))

# Main function to compute the answer
def compute_answer(x_list, y_list, n):
    x_sum = [0] * 100001
    y_sum = [0] * 100001
    count = 0

    for i in range(1, n + 1):
        x_sum[x_list[i - 1]] += i
        y_sum[y_list[i - 1]] += i

    for mask in range(1 << n):
        min_x = n + 1
        max_x = 0
        min_y = n + 1
        max_y = 0

        for i in range(n):
            if mask & (1 << i):
                v1, v2, v3, v4 = x_list[i], y_list[i], x_list[i], y_list[i]
                if mask & (1 << i - 1):
                    v1, v2 = [x_list[i - 1] + x, y_list[i - 1] + y] for x, y in [
                        [v2, v3],
                        [v3, v4],
                        [v1, v2],
                    ]
                if mask & (1 << i + 1):
                    v1, v2 = [x_list[i + 1] + x, y_list[i + 1] + y] for x, y in [
                        [v4, v3],
                        [v2, v1],
                        [v1, v2],
                    ]

                min_x = min(min_x, min(v1, v2))
                max_x = max(max_x, max(v1, v2))
                min_y = min(min_y, min(v3, v4))
                max_y = max(max_y, max(v3, v4))

        delta_y = min_x * (n + 1) - y_sum[min_x]
        delta_x = -x_sum[max_x] * (n + 1) + x_sum[max_x]
        delta_x += delta_y / (min_x - max_x * (delta_y // delta_x))

        for tup in get_blocking_tuples([[min_x, max_x + 1], [min_y, max_y + 1]]):
