import itertools

def find_max_xor(N, A, B):
    max_xor = 0
    for mask in range(1, 2**N):
        is_good = True
        for i in range(1, N + 1):
            if ((mask >> (i - 1)) & 1) * A[i - 1] != (mask >> (i - 1)) * B[i - 1] or not (1 << (i - 1)):
                is_good = False
                break
            else:
                mask ^= B[i - 1]
        if is_good:
            max_xor = max(max_xor, mask)
    return max_xor

