def max_nice_rectangles(grid):
    zero_indices = set(range(len(grid)))
    zero_indices_to_leaves = defaultdict(set)

    def dfs(index, parent):
        leaves = {index}
        for neighbor in range(len(grid)):
            if grid[neighbor] == 0 and neighbor != index and (neighbor not in leaves or neighbor in leaves and neighbor != parent):
                new_leaves = dfs(neighbor, index)
                leaves.update(new_leaves)
                zero_indices_to_leaves[index].update(new_leaves)
        return leaves

    dfs(0, -1)

    max_rectangles = 0
    reachable_cells = set()
    zero_indices_to_reachable = defaultdict(set)

    stack = zero_indices[:]

    while stack:
        cell = stack.pop()
        reachable_cells.add(cell)

        for next_index in zero_indices_to_leaves[cell]:
            if next_index not in reachable_cells:
                stack.append(next_index)

    for cell in reachable_cells:
        leaves = dfs(cell, -1)
        if len(leaves) > 1:
            zero_indices_to_reachable[cell] = leaves

    for cell in zero_indices:
        if cell not in reachable_cells:
            continue

        subtree = dfs(cell, -1)

        for node in subtree:
            if node in zero_indices_to_reachable and node in reachable_cells:
                max_rectangles = max(max_rectangles, len(subtree) + len(zero_indices_to_reachable[node]) - 1)

    return max_rectangles

