from math import comb

def count_arrays(N, x, y):
    q = (N - x - y) // 2
    r = (N - x - y) % 2
    if r > y:
        return 0  # Not possible
    k = min(x, y)
    for t in range(min(q, r), min(q + k, min(x, y) + y - k) + 1):
        if t < y + 2 * k or (x + y - 2 * k) % 2 == 0:
            break
    if t == r + k + 1:
        return comb(N - 1, x) *(comb(N - 1, y - k) - comb(t - 2 * k - 1, x - k)) % 998244353
    else:
        return 0

