import sys

def choose_intervals(n, k):
    if k == 0:
        return 1
    if n == 0:
        return 0
    if k > n:
        return 0
    # We can make at most 2^k intervals intersect
    if k <= n//2:
        return (2**k - 2)**n % (10**9 + 7)
    # In this case, all the intervals are non-adjacent
    return (2**n - 2)**n % (10**9 + 7)

